#!/usr/bin/env python3
import sys, os, shutil
sys.path.insert(0, "/tmp/work/mdblock")
from run import render, body

PREFIX = "  <h1 id = 'link-1'><span class = 'chapter-header'>Chapter 1</span></h1>"

def T(label, md, opts=None, strip=True, **kw):
    p, txt, d = render(md, opts, **kw)
    b = body(txt)
    print("### %s" % label)
    print("IN : %r" % md)
    if opts: print("OPT: %r" % opts)
    if p.stderr.strip(): print("ERR: %s" % p.stderr.strip())
    if strip and b is not None and b.startswith(PREFIX):
        b = b[len(PREFIX):]
        print("OUT(-title): %r" % b)
    else:
        print("OUT: %r" % b)
    print()
    shutil.rmtree(d, ignore_errors=True)
    return b

